class Solution { public int reachableNodes(int[][] edges,int maxMoves,int n){List<int[]>[] graph=new List[n];for(int i=0;i<n;i++)graph[i]=new ArrayList<>();for(int[] edge:edges){graph[edge[0]].add(new int[]{edge[1],edge[2]+1});graph[edge[1]].add(new int[]{edge[0],edge[2]+1});}long[] distance=new long[n];Arrays.fill(distance,Long.MAX_VALUE);distance[0]=0;PriorityQueue<long[]> heap=new PriorityQueue<>(Comparator.comparingLong(a->a[0]));heap.offer(new long[]{0,0});while(!heap.isEmpty()){long[] state=heap.poll();int node=(int)state[1];if(state[0]!=distance[node])continue;for(int[] edge:graph[node]){long next=state[0]+edge[1];if(next<distance[edge[0]]){distance[edge[0]]=next;heap.offer(new long[]{next,edge[0]});}}}long answer=0;for(long value:distance)if(value<=maxMoves)answer++;for(int[] edge:edges){long fromU=distance[edge[0]]<=maxMoves?maxMoves-distance[edge[0]]:0,fromV=distance[edge[1]]<=maxMoves?maxMoves-distance[edge[1]]:0;answer+=Math.min((long)edge[2],fromU+fromV);}return(int)answer;} }
